import os
import sys

print("CWD:", os.getcwd())
print("Files in CWD:")
for name in sorted(os.listdir(".")):
    full = os.path.join(".", name)
    if os.path.isfile(full):
        print("  FILE", name, os.path.getsize(full))
    else:
        print("  DIR ", name)

for mod in ("pypdf", "reportlab", "pdfplumber"):
    try:
        __import__(mod)
        print("module OK:", mod)
    except Exception as exc:
        print("module MISSING:", mod, "->", exc)

print("sys.version:", sys.version)

